# Curated question bank for the AI Mock Interview module.
# Each entry: role, interview_type, difficulty, question_format, question_text,
# expected_keywords (comma-separated concepts used for rule-based scoring),
# sample_answer (shown to the student as a model answer after they respond).

APTITUDE = [
    dict(role="Any", interview_type="aptitude", difficulty="easy", question_format="concept",
         question_text="A train travels 60 km in 1.5 hours. What is its speed in km/h?",
         expected_keywords="40, speed, distance, time, divide",
         sample_answer="Speed = Distance / Time = 60 / 1.5 = 40 km/h."),
    dict(role="Any", interview_type="aptitude", difficulty="easy", question_format="concept",
         question_text="If a shirt costs ₹800 after a 20% discount, what was its original price?",
         expected_keywords="1000, discount, percentage, original price",
         sample_answer="800 is 80% of the original price, so original = 800 / 0.8 = ₹1000."),
    dict(role="Any", interview_type="aptitude", difficulty="easy", question_format="concept",
         question_text="What is the next number in the series: 2, 4, 8, 16, ?",
         expected_keywords="32, double, pattern, multiply by 2",
         sample_answer="Each term doubles the previous one, so the next number is 32."),
    dict(role="Any", interview_type="aptitude", difficulty="medium", question_format="concept",
         question_text="Two pipes can fill a tank in 6 hours and 8 hours respectively. How long will it take if both are opened together?",
         expected_keywords="rate, LCM, 24/7, work, combined rate",
         sample_answer="Combined rate = 1/6 + 1/8 = 7/24 per hour, so time = 24/7 ≈ 3.43 hours."),
    dict(role="Any", interview_type="aptitude", difficulty="medium", question_format="concept",
         question_text="A is twice as old as B. Five years ago, A was three times as old as B. Find their current ages.",
         expected_keywords="equation, age, twice, linear equation, 20, 10",
         sample_answer="Let B = x, A = 2x. (2x-5) = 3(x-5) => 2x-5=3x-15 => x=10, so B=10, A=20."),
    dict(role="Any", interview_type="aptitude", difficulty="medium", question_format="concept",
         question_text="In how many ways can the letters of the word 'TABLE' be arranged?",
         expected_keywords="permutation, factorial, 120, 5!",
         sample_answer="All 5 letters are distinct, so arrangements = 5! = 120."),
    dict(role="Any", interview_type="aptitude", difficulty="hard", question_format="concept",
         question_text="A boat travels 30 km upstream in 6 hours and the same distance downstream in 3 hours. Find the speed of the boat and the current.",
         expected_keywords="upstream, downstream, relative speed, 7.5, 2.5",
         sample_answer="Upstream speed = 5 km/h, downstream = 10 km/h. Boat speed = (10+5)/2 = 7.5 km/h, current = (10-5)/2 = 2.5 km/h."),
    dict(role="Any", interview_type="aptitude", difficulty="hard", question_format="concept",
         question_text="If the probability of an event is 0.3, what is the probability that it does NOT occur in 2 independent trials?",
         expected_keywords="0.49, independent, complement, 0.7, probability",
         sample_answer="P(not occur once) = 0.7. For 2 independent trials, P(never occurs) = 0.7 × 0.7 = 0.49."),
    dict(role="Any", interview_type="aptitude", difficulty="hard", question_format="concept",
         question_text="A sum of money doubles itself in 8 years at simple interest. In how many years will it triple?",
         expected_keywords="simple interest, rate, 16, double, triple",
         sample_answer="Doubling in 8 years means rate = 12.5%/year. To triple (gain = 2x principal) takes 2/0.125 = 16 years."),
    dict(role="Any", interview_type="aptitude", difficulty="medium", question_format="concept",
         question_text="What is the time complexity of binary search, and why?",
         expected_keywords="O(log n), divide, sorted array, halves",
         sample_answer="O(log n) - each comparison halves the search space, so it takes log base 2 of n steps."),
]

