    dict(role="Python Developer", interview_type="technical", difficulty="medium", question_format="concept",
         question_text="What are Python decorators and how do they work?",
         expected_keywords="function wrapping, @ syntax, higher-order function, closures",
         sample_answer="Decorators wrap a function to extend its behavior without modifying it directly, implemented as higher-order functions using the @decorator syntax."),
    dict(role="Python Developer", interview_type="technical", difficulty="medium", question_format="coding",
         question_text="How would you remove duplicates from a list while preserving order? Explain your approach.",
         expected_keywords="dict.fromkeys, set, order preserving, O(n)",
         sample_answer="Use dict.fromkeys(list) which preserves insertion order since Python 3.7, or iterate while tracking seen items in a set - both O(n)."),
    dict(role="Python Developer", interview_type="technical", difficulty="hard", question_format="concept",
         question_text="Explain the difference between multiprocessing and multithreading in Python, and when you'd use each.",
         expected_keywords="GIL, CPU-bound, I/O-bound, separate processes, shared memory",
         sample_answer="Multithreading is good for I/O-bound tasks (limited by GIL for CPU work); multiprocessing spawns separate processes with their own memory, bypassing the GIL for true CPU-bound parallelism."),
